 "content": "def transform(grid):
    """Move the non-background pattern down by one row."""
    if not grid:
        return []
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [[background] * w for _ in range(h)]
    for r in range(1, h):
        for c in range(w):
            if grid[r - 1][c] != background:
                out[r][c] = grid[r - 1][c]
    return out
